import blessed from 'blessed';
import chalk from 'chalk';
import { ensureRepo } from '../utils/git.js';

export async function showDashboard() {
  let gitClient;
  try {
    gitClient = await ensureRepo();
  } catch (err) {
    console.error((err as Error)?.message || 'This command must be run inside a git repository.');
    process.exit(1);
  }

  const screen = blessed.screen({ smartCSR: true, title: 'gitcli dashboard', fullUnicode: true });
  const statusBox = blessed.box({
    label: 'Status',
    border: 'line',
    style: { border: { fg: 'cyan' }, label: { fg: 'cyan' } },
    padding: 1,
    top: 0,
    left: 0,
    width: '33%',
    height: '50%'
  });
  const commitsBox = blessed.box({
    label: 'Recent commits',
    border: 'line',
    style: { border: { fg: 'magenta' }, label: { fg: 'magenta' } },
    padding: 1,
    top: 0,
    left: '33%',
    width: '34%',
    height: '50%'
  });
  const dirtyBox = blessed.box({
    label: 'Dirty files',
    border: 'line',
    style: { border: { fg: 'red' }, label: { fg: 'red' } },
    padding: 1,
    top: 0,
    left: '67%',
    width: '33%',
    height: '50%',
    scrollable: true,
    alwaysScroll: true
  });
  const branchBox = blessed.box({
    label: 'Branch graph',
    border: 'line',
    style: { border: { fg: 'green' }, label: { fg: 'green' } },
    padding: 1,
    top: '50%',
    left: 0,
    width: '100%',
    height: '50%',
    scrollable: true,
    alwaysScroll: true
  });

  screen.append(statusBox);
  screen.append(commitsBox);
  screen.append(dirtyBox);
  screen.append(branchBox);

  let autoRefreshTimer: NodeJS.Timeout | null = null;

  async function render() {
    const status = await gitClient.status();
    const branchCount = (await gitClient.branchLocal()).all.length;
    const dirtyPenalty = status.files.length > 5 ? 20 : status.files.length * 2;
    const healthScore = Math.max(0, 100 - dirtyPenalty - Math.max(0, branchCount - 10));
    statusBox.setContent(
      `${chalk.bold('On')} ${status.current}\n` +
      `${chalk.green('Added')}: ${status.created.length}\n` +
      `${chalk.yellow('Modified')}: ${status.modified.length}\n` +
      `${chalk.red('Untracked')}: ${status.not_added.length}\n` +
      `${chalk.cyan('Health')}: ${healthScore}`
    );

    const log = await gitClient.log({ n: 5 });
    const formattedLog = log.all
      .map(l => `${chalk.blue(l.hash.slice(0, 7))} ${l.message}`)
      .join('\n');
    commitsBox.setContent(formattedLog);

    const dirtyLines =
      status.files.length === 0
        ? 'Clean working tree'
        : status.files.map(f => `${f.index}${f.working_dir} ${f.path}`).join('\n');
    dirtyBox.setContent(dirtyLines);

    const graph = await gitClient.raw(['log', '--oneline', '--graph', '--decorate', '--all', '--max-count=20']);
    branchBox.setContent(graph);
    screen.render();
  }

  await render();

  screen.key(['q', 'C-c', 'escape'], () => process.exit(0));
  screen.key(['r'], async () => {
    statusBox.setContent('Refreshing...');
    commitsBox.setContent('');
    branchBox.setContent('');
    await render();
  });

  screen.key(['g'], () => {
    branchBox.scrollTo(0);
    screen.render();
  });
  screen.key(['G'], () => {
    branchBox.scrollTo(branchBox.getLines().length);
    screen.render();
  });

  screen.key(['s'], async () => {
    statusBox.setContent('Refreshing status...');
    await render();
  });

  screen.key(['a'], () => {
    if (autoRefreshTimer) {
      clearInterval(autoRefreshTimer);
      autoRefreshTimer = null;
      statusBox.setContent(statusBox.getContent() + '\nAuto-refresh: off');
      screen.render();
      return;
    }
    autoRefreshTimer = setInterval(() => render(), 15000);
    statusBox.setContent(statusBox.getContent() + '\nAuto-refresh: on (15s)');
    screen.render();
  });

  screen.key(['d'], () => {
    dirtyBox.scroll(1);
    screen.render();
  });
  screen.key(['u'], () => {
    dirtyBox.scroll(-1);
    screen.render();
  });

  screen.render();
}
